import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a {rows}x{cols} chessboard, exactly the columns with indices in [blocked_cols] are completely blocked (all squares in those columns are unavailable). You may place 1x2 dominos horizontally only on the remaining squares. Arrange the dominos so that no domino can slide left or right when all others remain fixed. Determine the minimal possible value of m.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct a board where certain columns are fully blocked,
# and the unblocked columns form even-width corridors.
# The minimal m is rows * ((total unblocked columns)/2).
# We ensure feasibility: each corridor has even positive width.
for _ in range(100):
  rows = rng.randint(6, 14)
  cols = rng.randint(8, 20)
  # Choose B (number of blocked columns) so that:
  # 1) B >= 1
  # 2) S = cols - B is even (so parity(B) == parity(cols))
  # 3) S >= 2*(B+1) to allow splitting into positive even widths
  #    => cols - B >= 2B + 2 => cols >= 3B + 2 => B <= floor((cols - 2)/3)
  max_B = (cols - 2) // 3
  if max_B < 1:
      continue
  # Choose B with same parity as cols, in [1, max_B]
  candidates = [b for b in range(1, max_B + 1) if (b % 2) == (cols % 2)]
  if not candidates:
      continue
  B = rng.choice(candidates)
  g = B + 1  # number of corridors (gaps)
  S = cols - B  # total number of unblocked columns
  # Build g even-positive widths summing to S
  widths = [2] * g
  remaining = S - 2 * g
  # remaining is even and >= 0 by construction
  while remaining > 0:
      i = rng.randrange(g)
      widths[i] += 2
      remaining -= 2
  # Derive blocked column positions from widths
  blocked_cols = []
  pos = 0
  for i in range(g - 1):
      pos += widths[i]
      # Next column is blocked
      blocked = pos + 1
      # Sanity check
      if blocked < 1 or blocked > cols:
          break
      blocked_cols.append(blocked)
      pos += 1  # account for the blocked column itself
  if len(blocked_cols) != B:
      continue
  # Final checks: uniqueness, sorted, within bounds
  if sorted(set(blocked_cols)) != blocked_cols:
      continue
  return {'rows': rows, 'cols': cols, 'blocked_cols': blocked_cols}
# Fallback deterministic valid instance if randomness fails
rows, cols = 8, 14
# Choose B=4 with same parity as cols (cols%2=0), B%2=0 ok
blocked_cols = [3, 7, 10, 13]
return {'rows': rows, 'cols': cols, 'blocked_cols': blocked_cols}

    def verifier(assign):
# Validate and compute minimal m.
# Dominos are horizontal-only. Columns in blocked_cols are fully blocked.
# No horizontal slides means within each row, every corridor must be fully tiled by dominos,
# which is possible iff each corridor width is even. Minimal m equals rows * (total_unblocked/2).
try:
    rows = int(assign['rows'])
    cols = int(assign['cols'])
    blocked_cols = list(assign['blocked_cols'])
except Exception:
    # Invalid assignment structure
    return (False, None)

# Basic domain checks
if not (isinstance(rows, int) and isinstance(cols, int)):
    return (False, None)
if rows < 2 or cols < 2:
    # Too small to be nontrivial
    return (False, None)
if not isinstance(blocked_cols, list) or any((not isinstance(x, int)) for x in blocked_cols):
    return (False, None)
if len(blocked_cols) == 0:
    # At least one blocked column required to create nontrivial corridor decomposition
    return (False, None)
# Validate blocked_cols sorted, unique, in range
if sorted(set(blocked_cols)) != blocked_cols:
    return (False, None)
if any(x < 1 or x > cols for x in blocked_cols):
    return (False, None)

# Compute corridor widths from blocked columns
B = len(blocked_cols)
blocked_set = set(blocked_cols)
widths = []
w = 0
g_count = 0
for c in range(1, cols + 1):
    if c in blocked_set:
        # end of a corridor
        widths.append(w)
        g_count += 1
        w = 0
    else:
        w += 1
# last corridor
widths.append(w)
g_count += 1

# Check consistency: number of corridors g = B + 1
if g_count != B + 1:
    # inconsistent input
    return (False, None)
# Every width must be positive even to allow full tiling by horizontal dominos
if any(wi <= 0 or (wi % 2) != 0 for wi in widths):
    # Invalid instance: odd-width corridor would make jamming impossible in horizontal-only setting
    return (False, None)

total_unblocked = sum(widths)
# Minimal m: each row must fully tile its unblocked squares; dominos cover 2 squares each
answer = rows * (total_unblocked // 2)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

